    {
      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The geometric and topological aspects of quantum phase changed both the conceptual structure and experimental practice of quantum physics.",
        "attribution": "Aharonov and Berry represent two landmark formulations of observable quantum phase; their joint recognition is intellectually compelling, though the effects arose in distinct historical settings.",
        "maturity": "The effects have been repeatedly observed and became central tools across quantum, condensed-matter, and optical physics.",
        "uncertainties": [
          "Whether the Aharonov-Bohm effect and Berry phase should be treated as one sufficiently unified prize discovery."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have made time and frequency measurement a qualitatively more precise probe of nature.",
        "attribution": "Katori pioneered the magic-wavelength lattice-clock concept, while Ye made decisive independent experimental advances and demonstrations.",
        "maturity": "Performance, reproducibility, and broad scientific utility are established across several laboratories.",
        "uncertainties": [
          "The eventual definition of the prize-worthy discovery may require additional credit for the wider optical-clock lineage."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided one of the cleanest realizations of controllable many-qubit quantum physics and quantum information processing.",
        "attribution": "Cirac and Zoller supplied foundational proposals, and Blatt led defining experimental realizations.",
        "maturity": "High-fidelity control, entanglement, simulation, and computing demonstrations make this a mature platform.",
        "uncertainties": [
          "Credit is difficult to compress because the experimental and theoretical trapped-ion community is extensive."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory supplied a powerful nonperturbative framework for correlated electrons and transformed quantitative materials theory.",
        "attribution": "Vollhardt and collaborators developed the underlying limit, while Georges and Kotliar made the method broadly operational and influential.",
        "maturity": "Its conceptual basis and usefulness for correlated materials have endured for decades.",
        "uncertainties": [
          "The layered theoretical development makes a three-person attribution necessarily selective."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps established a new way to control light through the structure of a material rather than conventional optical elements.",
        "attribution": "John and Yablonovitch gave seminal concepts, while Joannopoulos provided foundational theoretical development for the field.",
        "maturity": "The physics is robust and has seeded a broad experimental and technological literature.",
        "uncertainties": [
          "Applications are diverse, but a single experimentally decisive realization is less clearly identifiable than for some higher-ranked candidates."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made coherent quantum optics with artificial superconducting atoms experimentally accessible and deeply reshaped quantum-device science.",
        "attribution": "Blais provided a seminal theoretical formulation, and Wallraff and Schoelkopf delivered a defining experimental demonstration.",
        "maturity": "The regime is robust, reproduced worldwide, and remains fundamental to superconducting quantum information.",
        "uncertainties": [
          "Its conceptual and experimental proximity to the 2025 recognition of superconducting quantum circuits requires careful boundary setting."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Oskar Painter",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics achieved exquisite measurement and quantum control of mechanical motion, connecting quantum optics to macroscopic resonators.",
        "attribution": "These researchers made complementary, field-defining contributions to theory, devices, and quantum-regime experiments.",
        "maturity": "Ground-state cooling, quantum-limited measurement, and coherent control have been convincingly demonstrated.",
        "uncertainties": [
          "The field has several other strong claimants to foundational credit."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry turned matter-wave coherence into a remarkably sensitive instrument for gravimetry, inertial sensing, and precision tests.",
        "attribution": "Bordé developed essential interferometric ideas, Pritchard advanced atom-optical methods, and Kasevich delivered landmark precision experiments.",
        "maturity": "The techniques are well established and widely used in fundamental and applied precision measurement.",
        "uncertainties": [
          "The contribution overlaps with a broad history of atom optics and interferometric metrology."
        ]
      }
    }
  ]
}
